// Helper: format entry as text line
function fmt(cat, obj) {
  return `  {n:'${obj.n}',la:${obj.la},ln:${obj.ln},sub:'${obj.sub}',desc:'${obj.desc}',fact:'${obj.fact}'},`;
}

for (const cat of categories) {
  const start = html.indexOf(`D.${cat} = [`);
  const end = html.indexOf('];', start);
  if (start === -1 || end === -1) { console.log('ERROR: category ' + cat + ' not found'); continue; }

  const before = html.substring(0, end);
  const after = html.substring(end);
  let content = html.substring(start, end);

  // Count existing entries
  const entryRegex = /\{n:/g;
  let count = 0;
  let match;
  while ((match = entryRegex.exec(content)) !== null) count++;

  if (count >= E[cat].length) { console.log(`${cat}: ${count} entries (all done)`); continue; }

  console.log(`${cat}: existing ${count}, adding ${E[cat].length - count} more`);

  // Build new entries text
  let newText = '';
  for (let i = count; i < E[cat].length; i++) {
    newText += fmt(cat, E[cat][i]) + '\n';
  }

  // Insert before the ];
  const newContent = before + '\n' + newText + after;
  html = newContent;
}

fs.writeFileSync(filePath, html, 'utf8');
console.log('DONE - file written successfully');
